// User-Overrides aus localStorage einlesen (für eigene Aktualisierungen)
try {
  const overrides = JSON.parse(localStorage.getItem('gm_country_overrides') || '{}');
  Object.assign(window.COUNTRIES, overrides);
} catch {}

// Globale Almanac-Funktion: liefert Profil + Hinweis falls fehlt
window.getCountryProfile = function(iso2) {
  if (!iso2) return null;
  const key = iso2.toUpperCase();
  return window.COUNTRIES[key] || null;
};

window.COUNTRY_DATA_NOTE = 'Stand: Anfang 2026. Manche Daten ändern sich häufig. Bei wichtigen Entscheidungen aktuelle Quellen prüfen.';
